function restoreFocus(key){
 if(!key)return;
 const descriptor=key.action?['[data-action]','action',key.action]:key.academyAction?['[data-academy-action]','academyAction',key.academyAction]:key.videoAction?['[data-video-action]','videoAction',key.videoAction]:key.accessAction?['[data-access-action]','accessAction',key.accessAction]:key.securityAction?['[data-security-action]','securityAction',key.securityAction]:null;
 const matches=el=>el.dataset?.[descriptor[1]]===descriptor[2]&&[['id','record'],['accessMember','accessMember'],['securityId','securityId'],['value','value'],['course','course'],['lesson','lesson'],['module','module'],['scope','scope'],['focus','workFocus'],['owner','owner'],['section','section'],['index','index']].every(([attribute,property])=>el.dataset?.[attribute]===key[property]);
 const el=key.id?document.getElementById?.(key.id):key.complete?Array.from(document.querySelectorAll('[data-complete]')).find(e=>e.dataset.complete===key.complete):key.subtask?Array.from(document.querySelectorAll('[data-subtask]')).find(e=>e.dataset.subtask===key.subtask):descriptor?Array.from(document.querySelectorAll(descriptor[0])).find(matches):key.submit?formSubmit(Array.from(document.querySelectorAll('form[data-form]')).find(e=>e.dataset.form===key.form)):null;
 el?.focus();
}
