function taskRows(tasks){return tasks.length?`<div class="task-list">${tasks.map(t=>`<div class="task-row ${t.status==='Done'?'completed':''}"><input type="checkbox" ${t.status==='Done'?'checked':''} aria-label="${t.status==='Done'?'Reopen':'Complete'} ${esc(t.title)}" data-complete="${t.id}"><button class="task-open" data-action="open-task" data-id="${t.id}"><span class="title">${esc(t.title)}</span><small>NAM-${String(t.number).padStart(3,'0')} · ${esc(t.project_title||label(t.section))}${t.production_stage?' · '+esc(t.production_stage):''} · ${esc(t.priority)}</small></button>${badge(t.status)}<span class="due ${overdue(t)?'overdue':''}">${esc(due(t))}</span>${avatar(member(t.owner_id))}</div>`).join('')}</div>`:empty('No tasks in this view','Try another filter, or create the next piece of work.');}
