 const subtasks=`<section class="detail-section"><h3>Subtasks</h3>${t.subtasks.map(s=>`<label class="check-row"><input type="checkbox" ${s.completed?'checked':''} data-subtask="${s.id}"><span>${esc(s.title)}</span></label>`).join('')||'<small>No subtasks yet.</small>'}<form data-form="subtask" class="inline-form"><label class="sr-only" for="new-subtask">New subtask</label><input id="new-subtask" name="title" placeholder="Add a subtask…" value="${esc(t.__subtaskDraft||'')}" required maxlength="200"><button type="submit" class="button small">Add</button></form></section>`;
