 const history=`<section class="detail-section"><h3>Activity</h3><div class="history">${t.events.map(e=>`<div class="event"><b>${esc(e.actor_name)}</b> · ${esc(e.body)}<br>${timestamp(e.created_at)}</div>`).join('')}</div></section>`;
