async function changeTask(id,version,changes){try{return await api(`/tasks/${id}`,'PATCH',{expectedVersion:version,changes});}catch(e){if(e.status===409&&e.message.includes('open subtasks')&&confirm('This task has unfinished subtasks. Mark the parent complete and leave its subtasks open?'))return api(`/tasks/${id}`,'PATCH',{expectedVersion:version,changes:{...changes,confirmOpenSubtasks:true}});throw e;}}
async function afterTask(message='Task saved',context=null,acknowledged=null){
 const generation=state.routeVersion,actor=state.data?.actor?.id,id=context?.id||state.task?.id;
 await Promise.all([refresh(),visibleTaskWorkspace()?loadTasks():Promise.resolve()]);
 if(generation!==state.routeVersion||actor!==state.data?.actor?.id||context&&!sameTaskContext(context))return;
 render();
 if(id&&dialog.open){const result=acknowledged?.id===id?acknowledged:await api('/tasks/'+id);if(generation!==state.routeVersion||actor!==state.data?.actor?.id||context&&!sameTaskContext(context))return;const draft=context?taskDraft():null;state.task=result;taskDialog(draft);}toast(message);
}
