function salesError(error,form){const region=form?.querySelector('.form-error');if(region){region.innerHTML=esc(error.message)+(error.status===409?`<div class="form-actions">${button('Reload sales records','reload-sales','small')}</div>`:'');}else toast(error.message);}
async function salesCorrection(el){
  const action=el.dataset.action;if(action==='edit-activity'){activityEditor(el.dataset.id);return;}if(action==='edit-target'){targetEditor(el.dataset.id);return;}
  if(action==='reload-sales'){if(dialog.open&&dirtyDialog()&&!confirm('Discard your unsaved correction and reload the latest sales records?'))return;state.sales=await api('/sales');dialog.close();render();return;}
  if(action==='delete-activity'){
    const record=state.sales?.activities.find(a=>a.id===el.dataset.id);if(!record||!canCorrectActivity(record))throw new Error('This activity is not available for deletion.');
    if(!confirm('Delete this activity for '+record.context+'? It will leave activity totals; its audit history is retained.'))return;
    try{state.sales=await api('/sales/activities/'+encodeURIComponent(record.id),'DELETE',{expectedVersion:Number(el.dataset.version)});dialog.close();render();toast('Activity deleted. Totals updated.');}catch(error){salesError(error,el.closest('form'));}
  }
}
